/** نگاشت درصد (۰..۱۰۰) به سگمنت استاندارد ۱ تا ۷ */
function feria_disc_segment(int $pct): int
{
    $pct = max(0, min(100, $pct));
    return (int)min(7, (int)floor($pct / 14) + 1);
}

