/** انتخاب حالت تصمیم‌گیری بر اساس نمرات D و C */
function feria_disc_decision_mode(array $pct): string
{
    $d = (int)($pct['D'] ?? 0);
    $c = (int)($pct['C'] ?? 0);
    if ($d >= 60 && $d > $c + 10) return 'd_lead';
    if ($c >= 60 && $c > $d + 10) return 'c_lead';
    return 'balanced';
}

